#include <bits/stdc++.h>
using namespace std;constexpr int S=5,Q=3,K=4;using V=array<int,S>;using M=array<V,S>;using W=vector<int>;M A[K];V b[K];int iv[K];
V mv(const M&m,const V&v){V x{};for(int i=0;i<S;i++){int z=0;for(int j=0;j<S;j++)z+=m[i][j]*v[j];x[i]=z%Q;}return x;}
bool invm(M m,M&o){o={};for(int i=0;i<S;i++)o[i][i]=1;for(int k=0;k<S;k++){int p=k;while(p<S&&!m[p][k])p++;if(p==S)return false;swap(m[k],m[p]);swap(o[k],o[p]);int c=m[k][k];for(int j=0;j<S;j++){m[k][j]=m[k][j]*c%Q;o[k][j]=o[k][j]*c%Q;}for(int i=0;i<S;i++)if(i!=k&&m[i][k]){int z=m[i][k];for(int j=0;j<S;j++){m[i][j]=(m[i][j]-z*m[k][j]+9)%3;o[i][j]=(o[i][j]-z*o[k][j]+9)%3;}}}return true;}
vector<W>words(int d){vector<W>w(1);while(d--){vector<W>v;for(auto x:w)for(int t=0;t<K;t++)if(x.empty()||t!=iv[x.back()]){auto y=x;y.push_back(t);v.push_back(y);}w=move(v);}return w;}
W rev(W w){reverse(w.begin(),w.end());for(int&t:w)t=iv[t];return w;}
vector<V>control(const W&w){vector<V>m;for(int t:w){for(auto&v:m)v=mv(A[t],v);m.push_back(b[t]);}return m;}
int rref(vector<V>&m,vector<int>*piv=nullptr){int k=0;if(piv)piv->clear();for(int j=0;j<S&&k<(int)m.size();j++){int p=k;while(p<(int)m.size()&&!m[p][j])p++;if(p==(int)m.size())continue;swap(m[p],m[k]);int c=m[k][j];for(int h=0;h<S;h++)m[k][h]=m[k][h]*c%3;for(int i=0;i<(int)m.size();i++)if(i!=k&&m[i][j]){int z=m[i][j];for(int h=0;h<S;h++)m[i][h]=(m[i][h]-z*m[k][h]+9)%3;}if(piv)piv->push_back(j);k++;}return k;}
int rankw(const W&w){auto m=control(w);return rref(m);}
int pencil(const W&w){auto m=control(w);vector<int>p;int r=rref(m,&p);if(r!=3)return 0;bool seen[9]={};int cnt=0;for(int pos=0;pos<=3;pos++)for(int t=0;t<K;t++){V v=b[iv[t]];for(int j=pos;j<3;j++)v=mv(A[w[j]],v);for(int i=0;i<3;i++){int z=v[p[i]];for(int j=0;j<S;j++)v[j]=(v[j]-z*m[i][j]+9)%3;}int first=0;while(first<S&&!v[first])first++;if(first==S)continue;int c=v[first],code=0;for(int j=0;j<S;j++)if(find(p.begin(),p.end(),j)==p.end())code=3*code+v[j]*c%3;if(!seen[code]){seen[code]=true;cnt++;}}return cnt;}
int main(int ac,char**av){if(ac<7)return 2;int mode=stoi(av[1]),pw=stoi(av[5]);uint64_t seed=stoull(av[2]);long long steps=stoll(av[3]);string out=av[4];double limit=stod(av[6]);mt19937_64 rng(seed);for(int t=0;t<K;t++)iv[t]=t;if(mode)iv[0]=1,iv[1]=0;
auto conj=[&](int t,int i,int j,int c){for(int k=0;k<S;k++)A[t][i][k]=(A[t][i][k]+c*A[t][j][k])%3;for(int k=0;k<S;k++)A[t][k][j]=(A[t][k][j]-c*A[t][k][i]+9)%3;b[t][i]=(b[t][i]+c*b[t][j])%3;};
auto init=[&](){for(int t=0;t<K;t++){A[t]={};b[t]={};b[t][0]=1;for(int i=0;i<S;i++)A[t][i][i]=(i<3?1:2);for(int k=0;k<80;k++){int i=rng()%S,j=rng()%S;if(i!=j)conj(t,i,j,1+rng()%2);}}if(mode){do{for(auto&row:A[0])for(int&x:row)x=rng()%3;}while(!invm(A[0],A[1]));b[0]={1,1,0,1,0};b[1]=mv(A[1],b[0]);}};init();auto w5=words(5),w3=words(3);vector<W>u5,u3;for(auto w:w5)if(w<=rev(w))u5.push_back(w);for(auto w:w3)if(w<=rev(w))u3.push_back(w);
int br=0,bp=0;auto eval=[&](){br=bp=0;for(auto&w:u5)br+=5-rankw(w);if(pw)for(auto&w:u3)bp+=4-pencil(w);return 3*br+pw*bp;};
auto save=[&](long long it,int score){ofstream f(out+".json");f<<"{\"q\":3,\"s\":5,\"mode\":"<<mode<<",\"seed\":"<<seed<<",\"iteration\":"<<it<<",\"score\":"<<score<<",\"inverse_labels\":[";for(int t=0;t<K;t++)f<<(t?",":"")<<iv[t];f<<"],\"matrices\":[";for(int t=0;t<K;t++){if(t)f<<',';f<<'[';for(int i=0;i<S;i++){if(i)f<<',';f<<'[';for(int j=0;j<S;j++)f<<(j?",":"")<<A[t][i][j];f<<']';}f<<']';}f<<"],\"vectors\":[";for(int t=0;t<K;t++){if(t)f<<',';f<<'[';for(int i=0;i<S;i++)f<<(i?",":"")<<b[t][i];f<<']';}f<<"],\"ranks\":[";int full=0,pens=0;for(int i=0;i<(int)w5.size();i++){int r=rankw(w5[i]);if(r==5)full++;f<<(i?",":"")<<r;}f<<"],\"pencil_directions\":[";for(int i=0;i<(int)w3.size();i++){int p=pencil(w3[i]);if(p==4)pens++;f<<(i?",":"")<<p;}f<<"],\"full\":"<<full<<",\"pencils\":"<<pens<<"}";cerr<<"best "<<score<<" full "<<full<<" pencils "<<pens<<" step "<<it<<'\n';};
int val=eval(),best=val;array<M,K>ba;array<V,K>bb;copy(A,A+K,ba.begin());copy(b,b+K,bb.begin());save(0,best);auto start=chrono::steady_clock::now();long long done=0;
for(long long it=1;it<=steps;it++){done=it;if(it%5000==0&&chrono::duration<double>(chrono::steady_clock::now()-start).count()>limit)break;if(it%100000==0){if(rng()%4){copy(ba.begin(),ba.end(),A);copy(bb.begin(),bb.end(),b);}else init();val=eval();}array<M,K>oa;array<V,K>ob;copy(A,A+K,oa.begin());copy(b,b+K,ob.begin());int t=rng()%K,i=rng()%S,j=rng()%S,c=1+rng()%2;if(mode&&t<2){if(rng()%10==0){b[0][i]=(b[0][i]+c)%3;if(b[0]==V{}){copy(ob.begin(),ob.end(),b);continue;}}else A[0][i][j]=(A[0][i][j]+c)%3;if(!invm(A[0],A[1])){copy(oa.begin(),oa.end(),A);copy(ob.begin(),ob.end(),b);continue;}b[1]=mv(A[1],b[0]);}else{if(i==j)continue;if(rng()%10){conj(t,i,j,c);}else{V z{};for(int k=0;k<S;k++)z[k]=rng()%3;V v=mv(A[t],z);for(int k=0;k<S;k++)b[t][k]=(z[k]+v[k])%3;if(b[t]==V{}){copy(ob.begin(),ob.end(),b);continue;}}}
int nv=eval();double T=.05+3*pow(.01,(it%15000)/15000.);if(nv<=val||generate_canonical<double,53>(rng)<exp((val-nv)/T))val=nv;else{copy(oa.begin(),oa.end(),A);copy(ob.begin(),ob.end(),b);}if(val<best){best=val;copy(A,A+K,ba.begin());copy(b,b+K,bb.begin());save(it,best);if(!best)break;}}
cerr<<"DONE steps "<<done<<" best "<<best<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}
